chunk:
InvoiceLine:
  type: object
  required: [lineId, description, quantity, unitPrice, lineTotal]
  properties:
    lineId:      { type: string }
    productId:   { type: string }
    description: { type: string }
    quantity:    { type: number }
    unitPrice:   { type: number }
    discount:    { type: number }
    lineTotal:   { type: number }
    taxCode:     { type: string }
    taxAmount:   { type: number }

InvoiceTotals:
  type: object
  required: [subtotal, total, currency, amountDue]
  properties:
    subtotal:       { type: number }
    discount:       { type: number }
    tax:            { type: number }
    total:          { type: number }
    amountPaid:     { type: number }
    amountDue:      { type: number }
    currency:       { type: string, pattern: "^[A-Z]{3}$" }

PaymentInfo:
  type: object
  properties:
    terms:         { type: string, example: "NET30" }
    dueDate:       { type: string, format: date }
    paidDate:      { type: string, format: date }
    paymentRef:    { type: string, description: "Check number, ACH trace, wire ref" }
    paymentMethod: { type: string, enum: [CHECK, ACH, WIRE, CREDIT_CARD, CASH] }

Timestamps:
  type: object
  properties:
    createdAt:   { type: string, format: date-time }
    updatedAt:   { type: string, format: date-time }
    issuedAt:    { type: string, format: date-time }
    dueAt:       { type: string, format: date-time }
    paidAt:      { type: string, format: date-time }
